import{_ as e,o,c as d,a3 as r}from"./chunks/framework.cNy3aYYk.js";const p=JSON.parse('{"title":"Live Chat 2.0.0 — Proactive, CSAT, Transcript, IP Ban, Visitor Notes Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Live Chat 2.0.0 — Proactive, CSAT, Transcript, IP Ban, Visitor Notes Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/live-chat-2-0-0-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Live Chat 2.0.0 — Proactive, CSAT, Transcript, IP Ban, Visitor Notes Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/live-chat-2-0-0-production-readiness"}]]},"headers":[],"relativePath":"deployment/live-chat-2-0-0-production-readiness.md","filePath":"deployment/live-chat-2-0-0-production-readiness.md","lastUpdated":1794259478000}'),i={name:"deployment/live-chat-2-0-0-production-readiness.md"};function a(n,t,s,c,l,h){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="live-chat-2-0-0-—-proactive-csat-transcript-ip-ban-visitor-notes-production-readiness-audit" tabindex="-1">Live Chat 2.0.0 — Proactive, CSAT, Transcript, IP Ban, Visitor Notes Production Readiness Audit <a class="header-anchor" href="#live-chat-2-0-0-—-proactive-csat-transcript-ip-ban-visitor-notes-production-readiness-audit" aria-label="Permalink to &quot;Live Chat 2.0.0 — Proactive, CSAT, Transcript, IP Ban, Visitor Notes Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-10-23</td></tr><tr><td><strong>Status</strong></td><td><strong>Go</strong> — migrate catalog through <strong>2.0.0</strong>; deploy Backend (widget JS + new tables/columns) + Frontend; ensure scheduler runs <code>live-chat:scan-proactive</code></td></tr><tr><td><strong>Scope</strong></td><td>Free Communication module <code>live-chat</code> <strong>1.7.0 → 1.8.0 → 1.9.0 → 2.0.0</strong> (visitor intel, public identify, proactive rules scan, CSAT, transcript email, IP ban list, visitor notes; embed <code>?v=2.0.0</code>)</td></tr><tr><td><strong>Companion</strong></td><td><a href="./live-chat">Live Chat deployment</a> · <a href="./live-chat-1-5-0-production-readiness">1.5.0 / 1.5.1 readiness</a> · <a href="./live-chat-production-readiness">1.0.1 baseline</a> · <a href="/developer-guide/live-chat">Developer</a> · <a href="/user-guide/live-chat">User</a> · <a href="/user-guide/live-chat-overview">Overview</a> · <a href="/api/tenant-v1-live-chat">API</a> · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><p>Additive <strong>MINOR/PATCH</strong> chain culminating in catalog <strong>2.0.0</strong>. No new Spatie permissions. New scheduler command <strong><code>live-chat:scan-proactive</code></strong> (every minute, onOneServer). Prior <a href="./live-chat-production-readiness">1.0.1</a> and <a href="./live-chat-1-5-0-production-readiness">1.5.x</a> audits remain the baseline for CORS, send soft-fail, and typing.</p><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p><strong>2.0.0</strong> completes the Live Chat milestone: richer visitor intel on heartbeat, public <strong>identify</strong>, <strong>proactive rules</strong> that auto-open chats and send invite messages, post-close <strong>CSAT</strong>, optional <strong>transcript email</strong>, <strong>IP ban</strong> hashes, and persistent <strong>visitor notes</strong>. Agent-initiated invites from <strong>1.7.0</strong> share the same <code>LiveChatInvite</code> public channel delivery.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Migrate <strong>1.6.0 → 1.7.0</strong> (<code>2026_10_23_125323_…</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Migrate <strong>1.7.0 → 1.8.0</strong> visitor intel (<code>2026_10_23_125658_…</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Migrate <strong>1.8.0 → 1.9.0</strong> identify columns (<code>2026_10_23_130000_…</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Migrate <strong>1.9.0 → 2.0.0</strong> phase four (<code>2026_10_23_130100_…</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Tables: proactive rules, banned IPs, visitor notes; CSAT + widget flags</td><td><strong>Pass</strong></td></tr><tr><td>Public <code>identify</code>, expanded heartbeat/session intel</td><td><strong>Pass</strong></td></tr><tr><td><code>live-chat:scan-proactive</code> scheduled every minute</td><td><strong>Pass</strong></td></tr><tr><td>Public CSAT + widget <code>csat_enabled</code> / <code>email_transcript_on_close</code></td><td><strong>Pass</strong></td></tr><tr><td>Ban visitor + optional <code>ban_ip</code>; IP blocks session create</td><td><strong>Pass</strong></td></tr><tr><td>Automation trigger <code>live_chat.proactive_invite_sent</code> wired</td><td><strong>Pass</strong></td></tr><tr><td>Embed snippet <code>widgets/live-chat.js?v=2.0.0</code> (<code>WidgetScriptVersion</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Prior CORS / entitlement / PII / session TTL / send soft-fail gates</td><td><strong>Pass</strong> (unchanged)</td></tr><tr><td>Pest <code>LiveChatModuleTest</code> (intel, identify, proactive, CSAT, IP ban, notes, transcript, reactivate)</td><td><strong>Pass locally</strong> (2026-10-23; confirm CI on merge)</td></tr><tr><td>Playwright <code>npm run test:e2e:live-chat:headed</code> (one shared session, 11 tests)</td><td><strong>Pass locally</strong> 11/11 (2026-10-23; confirm CI on merge)</td></tr><tr><td>Docs hubs + <a href="./live-chat">2.0.0 deployment</a> + this page</td><td><strong>Pass</strong></td></tr></tbody></table><p><strong>Go / No-Go:</strong> <strong>Go</strong> after companion CI green and:</p><ol><li><code>php artisan migrate --force</code> (catalog through <strong>2.0.0</strong>)</li><li>Backend deploy serving updated <code>public/widgets/live-chat.js</code></li><li>Frontend SPA deploy (proactive rules UI, CSAT/transcript toggles, visitor notes, ban IP checkbox)</li><li>Confirm platform scheduler runs <strong><code>live-chat:scan-proactive</code></strong> alongside <code>live-chat:scan-idle</code> and <code>live-chat:purge-visitors</code></li><li>Staging smoke below; re-copy Settings embed snippet with <strong><code>?v=2.0.0</code></strong> (or purge CDN)</li></ol><p>Reverb remaining down does <strong>not</strong> block send, proactive open, or close; it degrades typing and live inbox updates (poll fallback remains). Transcript mail requires queue workers.</p><hr><h2 id="incident-→-remediation-map" tabindex="-1">Incident → remediation map <a class="header-anchor" href="#incident-→-remediation-map" aria-label="Permalink to &quot;Incident → remediation map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Risk</th><th>Mitigation</th></tr></thead><tbody><tr><td>Proactive spam</td><td>Rule <code>cooldown_minutes</code> + per-visitor <code>proactive_cooldowns</code>; tune <code>min_dwell_seconds</code> / <code>path_contains</code></td></tr><tr><td>CSAT on open chats</td><td>API rejects CSAT unless conversation <strong>closed</strong></td></tr><tr><td>Transcript mail failure blocks close</td><td>Close path soft-fails mail (<code>LiveChatTranscriptMail</code>)</td></tr><tr><td>IP ban false positive</td><td>Ban is optional checkbox; hashes stored per tenant — unban visitor does not auto-remove IP row (manage via support/runbook)</td></tr><tr><td>Stale embed after deploy</td><td>Snippet <code>?v=2.0.0</code> + redeploy</td></tr></tbody></table><hr><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to &quot;Findings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Status</th><th>Finding</th><th>Action</th></tr></thead><tbody><tr><td>LC20-01</td><td>Medium</td><td><strong>Fixed</strong></td><td>No automated proactive outreach</td><td>Rules + <code>live-chat:scan-proactive</code> + <code>LiveChatInvite</code></td></tr><tr><td>LC20-02</td><td>Medium</td><td><strong>Fixed</strong></td><td>No post-close satisfaction signal</td><td>Public CSAT endpoint + embed prompt</td></tr><tr><td>LC20-03</td><td>Low</td><td><strong>Fixed</strong></td><td>Visitors lose context after close</td><td>Optional transcript email on close</td></tr><tr><td>LC20-04</td><td>Medium</td><td><strong>Fixed</strong></td><td>Repeat abusers rotate visitor row</td><td>Optional <code>ban_ip</code> + <code>live_chat_banned_ips</code></td></tr><tr><td>LC20-05</td><td>Low</td><td><strong>Fixed</strong></td><td>No cross-thread visitor context</td><td>Visitor notes CRUD</td></tr><tr><td>LC20-06</td><td>Low</td><td><strong>Fixed</strong></td><td>Logged-in sites anonymous in desk</td><td>Public identify + custom attributes</td></tr><tr><td>LC20-07</td><td>High</td><td><strong>Fixed</strong></td><td>Re-entitle after cancel left widgets <code>is_active=false</code> → public 404</td><td><code>reactivateForTenant</code> on activate/install</td></tr><tr><td>LC20-08</td><td>High</td><td><strong>Fixed</strong></td><td>Bulk session revoke wrote one hash for all visitors (unique constraint)</td><td>Per-visitor unique revoke hashes</td></tr><tr><td>LC20-09</td><td>Medium</td><td><strong>Fixed</strong></td><td>Headed e2e invite dialog overlay blocked later clicks</td><td>Close invite dialog; Escape before inbox</td></tr></tbody></table><h3 id="ops-not-code-blockers" tabindex="-1">Ops (not code blockers) <a class="header-anchor" href="#ops-not-code-blockers" aria-label="Permalink to &quot;Ops (not code blockers)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Status</th><th>Finding</th><th>Owner</th></tr></thead><tbody><tr><td>O1</td><td>Medium</td><td>Open</td><td>Scheduler must run proactive + idle scans every minute</td><td>Ops</td></tr><tr><td>O2</td><td>Medium</td><td>Open</td><td>Queue workers for transcript mail when toggle enabled</td><td>Ops</td></tr><tr><td>O3</td><td>Low</td><td>Open</td><td>Customer embeds: refresh snippet to <code>?v=2.0.0</code> after deploy</td><td>CS</td></tr><tr><td>O4</td><td>Low</td><td>Open</td><td>Monitor proactive scan volume + mail failures</td><td>Ops</td></tr></tbody></table><h3 id="explicitly-deferred-unchanged" tabindex="-1">Explicitly deferred (unchanged) <a class="header-anchor" href="#explicitly-deferred-unchanged" aria-label="Permalink to &quot;Explicitly deferred (unchanged)&quot;">​</a></h3><ul><li>Captcha / Turnstile beyond throttle + session TTL</li><li>Bots / FAQ flows; invoice/record share in chat</li><li>Multi-widget / multi-domain brands</li><li>Full mobile agent desk parity</li></ul><hr><h2 id="test-evidence" tabindex="-1">Test evidence <a class="header-anchor" href="#test-evidence" aria-label="Permalink to &quot;Test evidence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Suite</th><th>Result</th><th>Notes</th></tr></thead><tbody><tr><td><code>php artisan test --compact tests/Feature/Tenant/LiveChat</code></td><td><strong>Pass locally</strong></td><td>Incl. reactivate-on-activate, unique revoke, intel/identify/proactive/CSAT/IP ban/notes/transcript</td></tr><tr><td><code>npm run test:e2e:live-chat:headed</code></td><td><strong>Pass locally 11/11</strong></td><td>One shared demo login: gate → entitle → invite dialog validation → filters → widget validation/save → regen key → visitor reply → notes/typing/canned → claim/close → lead create validation/link → search</td></tr></tbody></table><p>Do <strong>not</strong> claim remote CI green until companion PRs’ Quality Gates pass on the merge branch. Local headed + Pest evidence above is verified 2026-10-23.</p><hr><h2 id="deploy-order" tabindex="-1">Deploy order <a class="header-anchor" href="#deploy-order" aria-label="Permalink to &quot;Deploy order&quot;">​</a></h2><ol><li>Companion <strong>CI</strong> green (Backend / Frontend / Docs)</li><li><strong>Backend</strong> — <code>php artisan migrate --force</code> through <code>2026_10_23_130100_live_chat_phase_four_and_bump_to_2_0_0</code>; confirm catalog <code>live-chat</code> = <strong>2.0.0</strong> and <code>public/widgets/live-chat.js</code> matches <strong>2.0.0</strong>; <code>php artisan reverb:restart</code> if Reverb is used; Horizon/workers up for mail</li><li><strong>Frontend</strong> — SPA with proactive rules, CSAT/transcript settings, visitor notes, ban IP</li><li><strong>Docs</strong> — this page live</li><li>Staging smoke below before production marketing embeds</li></ol><p>Suggested merge order: <strong>Backend → Frontend → Docs</strong>.</p><hr><h2 id="pre-flight-checklist" tabindex="-1">Pre-flight checklist <a class="header-anchor" href="#pre-flight-checklist" aria-label="Permalink to &quot;Pre-flight checklist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Check</th><th>Owner</th><th>Pass?</th></tr></thead><tbody><tr><td>1</td><td>Migrate through <code>2026_10_23_130100_…</code>; catalog <code>live-chat</code> = <strong>2.0.0</strong></td><td>Ops</td><td>☐</td></tr><tr><td>2</td><td>API serves <code>GET {APP_URL}/widgets/live-chat.js</code>; Settings snippet uses <code>?v=2.0.0</code></td><td>Ops</td><td>☐</td></tr><tr><td>3</td><td>Scheduler: <code>live-chat:scan-proactive</code>, <code>live-chat:scan-idle</code>, <code>live-chat:purge-visitors</code></td><td>Ops</td><td>☐</td></tr><tr><td>4</td><td>Reverb up <strong>or</strong> accepted degraded typing/live inbox</td><td>Ops</td><td>☐</td></tr><tr><td>5</td><td>Queue workers running when transcript toggle used</td><td>Ops</td><td>☐</td></tr><tr><td>6</td><td>Pest Live Chat suite green on CI</td><td>Eng</td><td>☐</td></tr><tr><td>7</td><td>Playwright <code>test:e2e:live-chat</code> green on CI</td><td>QA</td><td>☐</td></tr></tbody></table><hr><h2 id="staging-smoke-human" tabindex="-1">Staging smoke (human) <a class="header-anchor" href="#staging-smoke-human" aria-label="Permalink to &quot;Staging smoke (human)&quot;">​</a></h2><ol><li>Marketplace: workspace with Live Chat <strong>2.0.0</strong> entitled; widget Active</li><li><strong>Intel:</strong> foreign Origin embed → heartbeat across two paths → Live visitors / visitor panel show page trail, device, UTM when present</li><li><strong>Identify:</strong> <code>POST …/identify</code> with <code>user_id</code> + attributes → panel shows external id + attributes</li><li><strong>Proactive:</strong> Settings rule (path + dwell 0) → live visitor on matching URL → within ~1 min invite message + open chat (badge/auto-open on embed)</li><li><strong>Agent invite:</strong> Live visitors <strong>Chat</strong> with body → same invite delivery as 1.7.0</li><li><strong>CSAT:</strong> close thread → embed shows 1–5 survey → submit succeeds</li><li><strong>Transcript:</strong> enable email transcript + visitor email → close → mail queued (check worker)</li><li><strong>Ban IP:</strong> ban with <strong>Also ban this IP</strong> → new session from same IP <strong>403</strong></li><li><strong>Visitor notes:</strong> add note on visitor → persists on reopen</li><li>Confirm Settings embed snippet contains <code>live-chat.js?v=2.0.0</code></li></ol><hr><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Action</th></tr></thead><tbody><tr><td>Frontend</td><td>Redeploy previous SPA</td></tr><tr><td>Backend code</td><td>Redeploy previous release; keep additive catalog/schema migrations</td></tr><tr><td>Proactive</td><td>Deactivate rules or disable scheduler line temporarily (stops auto-invites)</td></tr><tr><td>Module</td><td>Marketplace cancel / deactivate widgets (existing path)</td></tr><tr><td>Schema</td><td>No schema rollback — additive migrations only</td></tr></tbody></table><hr><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li><code>live-chat:scan-proactive</code> success / duration (scheduler logs)</li><li>Proactive invite volume vs rule count</li><li>Public CSAT <strong>422/403</strong> rate vs successful submissions</li><li><code>LiveChatTranscriptMail</code> queue failures</li><li>Banned IP <strong>403</strong> on <code>POST …/sessions</code></li><li>Existing: send soft-fail logs, throttle denials, Reverb health</li></ul><hr><h2 id="sign-off" tabindex="-1">Sign-off <a class="header-anchor" href="#sign-off" aria-label="Permalink to &quot;Sign-off&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Name</th><th>Date</th><th>Decision</th></tr></thead><tbody><tr><td>Eng</td><td></td><td></td><td>☐ Ready</td></tr><tr><td>QA</td><td></td><td></td><td>☐ Ready</td></tr><tr><td>Ops</td><td></td><td></td><td>☐ Ready</td></tr></tbody></table><p><strong>Release decision:</strong> <strong>Go</strong> — ship companions after CI green; migrate to catalog <strong>2.0.0</strong>, enable proactive scan, and redeploy embed <strong>v=2.0.0</strong> before relying on production marketing sites.</p>',44)])])}const u=e(i,[["render",a]]);export{p as __pageData,u as default};
